import{_ as e,o as i,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2016-SEP-07 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2016-SEP-07 :: Ceph Developer Monthly","date":"2016-09-08T00:00:00.000Z","updated":"2016-09-08T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","损坏纠正码","复制","快照","克隆","虚拟化存储","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表盘","管理","自动化","集成","容器化","Kubernetes","Docker","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑","失败域","恢复","弹性","负载均衡","缓存","压缩","数据去重","层次存储","性能调优","基准测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),s={name:"posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.md"};function t(p,l,n,a,_,u){return i(),o("div",null,[...l[0]||(l[0]=[r("<p><strong>会议时间</strong>： 2023年10月（具体日期未提及）</p><p><strong>会议主题</strong>： Ceph开发者月度会议</p><p><strong>参会人员</strong>： Jeans、Sage、Victor、Jason、Marcus、Dan、Alfredo、Basam、Vera、Sam等</p><p><strong>会议内容</strong>：</p><p><strong>一、RBD快照和一致性组</strong></p><ul><li>Sage提出了RBD快照和一致性组的设计方案，包括： <ul><li>在现有快照设计中添加“快照类型”字段，以区分用户快照和一致性组快照。</li><li>在图像类中添加“快照创建”函数，并添加“快照类型”参数，以指定创建的是用户快照还是一致性组快照。</li><li>创建内部函数“创建图像快照”和“创建一致性组快照”，以支持并行创建快照。</li><li>添加“获取快照ID”、“获取图像ID”和“获取快照信息”等功能，以方便用户获取快照信息。</li></ul></li><li>讨论了以下问题： <ul><li>如何处理快照创建过程中的异常情况，例如无法打开图像或获取独占锁失败。</li><li>如何处理快照创建失败的情况，例如部分快照已创建但无法提交。</li><li>如何区分用户快照和一致性组快照，以及如何处理命名冲突。</li></ul></li></ul><p><strong>二、Kerberos认证</strong></p><ul><li>讨论了使用Kerberos进行Ceph集群认证的方案，包括： <ul><li>定义新的认证类型“Kerberos 5”，直接与libkrb5库交互。</li><li>在监控器中实现认证逻辑，将用户身份映射到Ceph用户数据库。</li><li>考虑使用“混合令牌”机制，将用户身份与Ceph身份结合。</li></ul></li><li>讨论了以下问题： <ul><li>使用Kerberos认证的必要性。</li><li>Kerberos与其他认证方式的兼容性。</li><li>Kerberos认证的配置和管理。</li></ul></li></ul><p><strong>三、simd指令集检测</strong></p><ul><li>Basam提出了在EC库中实现simd指令集检测的方案，以支持不同处理器的优化。</li><li>讨论了以下问题： <ul><li>如何实现simd指令集检测。</li><li>如何处理不同指令集之间的兼容性问题。</li><li>如何迁移现有集群以使用新的simd指令集。</li></ul></li></ul><p><strong>四、其他议题</strong></p><ul><li>讨论了以下议题： <ul><li>Messenger 2计划。</li><li>Seth deploy、Seth anible和Seth installer的更新计划。</li><li>新的编码和解码功能。</li><li>AutoMake的升级。</li></ul></li></ul><p><strong>行动计划</strong>：</p><ul><li>Sage将进一步完善RBD快照和一致性组的设计方案，并与团队讨论细节。</li><li>Dan将负责Kerberos认证的实现。</li><li>Basam将负责simd指令集检测的实现。</li><li>其他团队成员将继续推进各自的工作计划。</li></ul><p><strong>后续会议</strong>：</p><ul><li>下次Ceph开发者月度会议将于2023年10月5日举行。</li></ul>",16)])])}const d=e(s,[["render",t]]);export{g as __pageData,d as default};
